?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz Background Remover</title><meta name="description" content="Remove image backgrounds quickly in your browser with SmartToolz."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,500,0,0&display=swap" rel="stylesheet"><style>:root{--p:#635bff;--p2:#8b7cff;--ink:#161923;--muted:#788093;--line:#e7e9ef;--bg:#f7f8fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif}.material-symbols-rounded{font-size:20px;line-height:1}.wrap{width:min(1040px,calc(100% - 28px));margin:0 auto;padding:18px 0 28px}.hero{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin:2px 0 12px}.kicker{font-size:9px;font-weight:800;letter-spacing:.65px;color:#5c54d7}.hero h1{margin:6px 0 4px;font-size:clamp(28px,4vw,42px);line-height:1.02;letter-spacing:-1.9px}.hero h1 span{color:var(--p)}.hero p{margin:0;color:var(--muted);font-size:10px}.guide{flex:0 0 auto;text-decoration:none;border:1px solid #dedbff;background:#fff;color:#554bd5;padding:9px 12px;border-radius:9px;font-size:8px;font-weight:800}.card{background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:0 12px 38px rgba(27,32,60,.06)}.toolbar{height:48px;padding:0 13px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.status{display:flex;align-items:center;gap:8px;font-size:8px;font-weight:800}.status i{width:7px;height:7px;border-radius:50%;background:#16a34a;box-shadow:0 0 0 4px #dcfce7}.toolbar button{border:1px solid var(--line);background:#fff;border-radius:8px;padding:7px 9px;color:#50596b;font-size:8px;font-weight:800;cursor:pointer}.workspace{padding:12px}.dropzone,.viewer{position:relative;border:1px solid var(--line);border-radius:14px;overflow:hidden}.dropzone{min-height:320px;display:grid;place-items:center;padding:18px;background:radial-gradient(circle at top,#fff,#f8f9fc 62%,#f5f6fa)}.dropzone.drag{border-color:var(--p);box-shadow:0 0 0 4px rgba(99,91,255,.08)}.dropbox{text-align:center}.upload-icon{width:54px;height:54px;margin:0 auto 11px;border-radius:15px;background:#efedff;color:#5a51d6;display:grid;place-items:center}.dropbox h2{margin:0;font-size:19px;letter-spacing:-.4px}.dropbox p{margin:6px auto 13px;max-width:410px;color:var(--muted);font-size:9px;line-height:1.6}.choose{display:inline-flex;align-items:center;gap:7px;padding:11px 17px;border-radius:10px;background:linear-gradient(135deg,var(--p),var(--p2));color:#fff;font-size:9px;font-weight:800;cursor:pointer;box-shadow:0 8px 20px rgba(99,91,255,.18)}.meta{margin-top:9px;font-size:7px;color:#a0a6b2}.viewer{display:none;min-height:0;padding:14px;align-items:center;justify-content:center;background:repeating-conic-gradient(#eef1f5 0 25%,#fafbfc 0 50%) 50%/22px 22px;transition:min-height .25s ease}.viewer.processing{min-height:330px}.viewer canvas{display:block;width:auto;height:auto;max-width:min(100%,860px);max-height:420px;border-radius:11px;box-shadow:0 14px 36px rgba(15,20,40,.14)}.scan{position:absolute;inset:0;display:none;align-items:center;justify-content:center;pointer-events:none}.scan-shade{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(255,255,255,.03),rgba(255,255,255,.2),rgba(255,255,255,.03))}.scan-line{position:absolute;left:7%;right:7%;height:2px;background:linear-gradient(90deg,transparent,#756dff 18%,#a79fff 50%,#756dff 82%,transparent);box-shadow:0 0 18px rgba(99,91,255,.7);animation:scan 2.1s ease-in-out infinite}.scan-card{position:relative;z-index:2;min-width:230px;padding:12px 15px;border:1px solid rgba(255,255,255,.72);border-radius:13px;background:rgba(18,21,31,.82);backdrop-filter:blur(12px);color:#fff;text-align:center;box-shadow:0 15px 42px rgba(20,22,34,.18)}.scan-card strong{display:block;font-size:8px}.scan-card span{display:block;margin-top:4px;color:#bfc4d2;font-size:7px}@keyframes scan{0%,100%{top:14%}50%{top:78%}}.progress{position:absolute;left:14px;right:14px;bottom:14px;max-width:500px;margin:auto;padding:10px 12px;background:#151822;color:#fff;border-radius:11px;z-index:4;box-shadow:0 8px 24px rgba(13,15,24,.22)}.progress-row{display:flex;justify-content:space-between;font-size:7px;font-weight:800}.track{height:4px;margin-top:7px;border-radius:99px;overflow:hidden;background:#303440}.track i{display:block;width:0;height:100%;background:linear-gradient(90deg,var(--p),var(--p2));transition:width .2s ease}.controls{display:none;gap:7px;padding-top:10px}.controls button{flex:1;border:1px solid var(--line);background:#fff;border-radius:9px;padding:10px;color:#525b6d;font-size:8px;font-weight:800;cursor:pointer}.controls .primary{border-color:#171925;background:#171925;color:#fff}.compare{display:none;margin-top:10px}.compare-head{display:flex;align-items:center;justify-content:space-between;padding:0 2px 7px}.compare-head b{font-size:10px}.compare-head span{font-size:7px;color:var(--muted)}.comparison{position:relative;height:min(350px,48vw);min-height:210px;border:1px solid var(--line);border-radius:13px;overflow:hidden;background:#dedfe4;user-select:none}.comparison img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.comparison .after{position:absolute;inset:0 auto 0 0;width:50%;overflow:hidden;border-right:2px solid #fff}.comparison .after img{width:100%;height:100%;object-fit:contain;min-width:100%}.comparison input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:ew-resize}.labels{position:absolute;top:8px;left:8px;right:8px;display:flex;justify-content:space-between;pointer-events:none}.labels span{padding:5px 7px;border-radius:6px;background:rgba(20,24,34,.72);color:#fff;font-size:6px;font-weight:800}.note{text-align:center;padding-top:6px;color:#979eaa;font-size:7px}@media(max-width:700px){.wrap{width:calc(100% - 14px);padding-top:12px}.hero{display:block}.guide{display:inline-flex;margin-top:9px}.dropzone{min-height:290px}.viewer.processing{min-height:300px}.viewer{padding:10px}.viewer canvas{max-height:350px}.scan-card{min-width:210px}.controls{flex-direction:column}.comparison{height:68vw;min-height:210px}}@media(max-width:420px){.hero h1{letter-spacing:-1.3px}.toolbar{padding:0 10px}.workspace{padding:9px}.dropzone{min-height:270px;padding:12px}.dropbox h2{font-size:18px}}</style></head><body><?php require_once __DIR__.'/../header.php'; ?><main class="wrap"><header class="hero"><div><div class="kicker">SMARTTOOLZ • BACKGROUND REMOVER</div><h1>Remove the background. <span>Keep the subject.</span></h1><p>One clear action. Fast browser processing. Your image stays in your browser.</p></div><a class="guide" href="/knowledge-base/image-background-remover/article/">How to use this tool</a></header><section class="card"><div class="toolbar"><div class="status"><i></i><span id="status">Ready to remove</span></div><button id="new" type="button">New image</button></div><div class="workspace"><div class="dropzone" id="drop"><div class="dropbox"><div class="upload-icon"><span class="material-symbols-rounded">content_cut</span></div><h2>Drop an image here</h2><p>or choose a photo to automatically remove its background.</p><label class="choose"><span class="material-symbols-rounded">upload_file</span> Choose image<input id="picker" hidden type="file" accept="image/png,image/jpeg,image/webp"></label><div class="meta">PNG • JPG • WebP</div></div></div><div class="viewer" id="viewer"><canvas id="out"></canvas><div class="scan" id="scan"><div class="scan-shade"></div><div class="scan-line"></div><div class="scan-card"><strong>Removing background</strong><span>SmartToolz is separating the subject…</span></div></div><div class="progress" id="progress"><div class="progress-row"><span>Removing background…</span><span id="pct">0%</span></div><div class="track"><i id="fill"></i></div></div></div><div class="controls" id="controls"><button id="again" type="button">Try another</button><button id="download" class="primary" type="button">Download PNG</button></div><div class="compare" id="compare"><div class="compare-head"><b>Before / After</b><span>Drag anywhere to compare</span></div><div class="comparison"><img id="before" alt="Original image"><div class="after" id="afterClip"><img id="after" alt="Background removed"></div><input id="slider" type="range" min="0" max="100" value="50" aria-label="Compare original and result"><div class="labels"><span>RESULT</span><span>ORIGINAL</span></div></div><div class="note">Transparent background is preserved in the downloaded PNG.</div></div></div></section></main><script type="module">import{removeBackground}from'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';const $=id=>document.getElementById(id);const picker=$('picker'),drop=$('drop'),viewer=$('viewer'),canvas=$('out'),ctx=canvas.getContext('2d'),scan=$('scan'),progress=$('progress'),fill=$('fill'),pct=$('pct'),status=$('status'),controls=$('controls'),compare=$('compare'),before=$('before'),after=$('after'),afterClip=$('afterClip'),slider=$('slider');let outputUrl='',sourceUrl='';function reset(){picker.value='';drop.style.display='grid';viewer.style.display='none';viewer.classList.remove('processing');scan.style.display='none';progress.style.display='none';controls.style.display='none';compare.style.display='none';status.textContent='Ready to remove';if(outputUrl)URL.revokeObjectURL(outputUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl);outputUrl='';sourceUrl='';afterClip.style.width='50%'}function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src})}function cropTransparent(im){const c=document.createElement('canvas'),x=c.getContext('2d',{willReadFrequently:true});c.width=im.naturalWidth;c.height=im.naturalHeight;x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height).data;let l=c.width,t=c.height,r=-1,b=-1;for(let y=0;y<c.height;y++){for(let xx=0;xx<c.width;xx++){if(d[(y*c.width+xx)*4+3]>8){if(xx<l)l=xx;if(xx>r)r=xx;if(y<t)t=y;if(y>b)b=y}}}if(r<0||b<0)return null;const pad=Math.max(6,Math.round(Math.min(c.width,c.height)*.012));l=Math.max(0,l-pad);t=Math.max(0,t-pad);r=Math.min(c.width-1,r+pad);b=Math.min(c.height-1,b+pad);const out=document.createElement('canvas');out.width=r-l+1;out.height=b-t+1;out.getContext('2d').drawImage(c,l,t,out,0,0,out.width,out.height);return out}async function process(file){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type))return;drop.style.display='none';viewer.style.display='flex';viewer.classList.add('processing');scan.style.display='flex';progress.style.display='block';controls.style.display='none';compare.style.display='none';status.textContent='Preparing image';sourceUrl=URL.createObjectURL(file);before.src=sourceUrl;try{const source=await loadImage(sourceUrl);const maxW=860,maxH=400;const scale=Math.min(maxW/source.naturalWidth,maxH/source.naturalHeight,1);canvas.width=Math.max(1,Math.round(source.naturalWidth*scale));canvas.height=Math.max(1,Math.round(source.naturalHeight*scale));ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,0,0,canvas.width,canvas.height);const blob=await removeBackground(file,{model:'small',output:{format:'image/png',quality:1},progress:(name,current,total)=>{const p=total?Math.max(4,Math.min(96,Math.round(current/total*92)+4)):8;fill.style.width=p+'%';pct.textContent=p+'%';status.textContent='Removing background'}});const im=await loadImage(URL.createObjectURL(blob));const cropped=cropTransparent(im);let finalBlob=blob;if(cropped){finalBlob=await new Promise(r=>cropped.toBlob(r,'image/png',1))||blob}outputUrl=URL.createObjectURL(finalBlob);const out=await loadImage(outputUrl);canvas.width=out.naturalWidth;canvas.height=out.naturalHeight;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(out,0,0);after.src=outputUrl;fill.style.width='100%';pct.textContent='100%';scan.style.display='none';viewer.classList.remove('processing');progress.style.display='none';controls.style.display='flex';compare.style.display='block';status.textContent='Background removed'}catch(err){console.error(err);scan.style.display='none';progress.style.display='none';status.textContent='Could not process image';drop.style.display='grid';viewer.style.display='none';viewer.classList.remove('processing')}}picker.onchange=()=>{const f=picker.files?.[0];picker.value='';process(f)};drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');process(e.dataTransfer.files?.[0])});$('new').onclick=reset;$('again').onclick=reset;$('download').onclick=()=>{if(!outputUrl)return;const a=document.createElement('a');a.href=outputUrl;a.download='smarttoolz-background-removed.png';document.body.appendChild(a);a.click();a.remove()};slider.oninput=()=>{afterClip.style.width=slider.value+'%'};window.addEventListener('beforeunload',()=>{if(outputUrl)URL.revokeObjectURL(outputUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl)});</script></body></html>